  "literacy.tutorial.title": "কলাকৃতিলৈ স্বাগতম — এইটোৱে কেনেকৈ কাম কৰে",
  "literacy.tutorial.subtitle": "শিল্পীসকলৰ বাবে সহজ ব্যৱস্থা। কম্পিউটাৰ জ্ঞান নোহোৱাকৈ সমগ্ৰ ভাৰতত বিক্ৰী কৰক।",
  "literacy.tutorial.step1Title": "১. নিজৰ মাতৃভাষাত কওক",
  "literacy.tutorial.step1Desc": "টাইপ কৰাৰ প্ৰয়োজন নাই। কেৱল নিজৰ ভাষাত সামগ্ৰীৰ বৰ্ণনা দিয়ক, আমাৰ AI য়ে লিখিব।",
  "literacy.tutorial.step2Title": "২. স্বয়ংক্ৰিয় AI ষ্টুডিঅ’ ফটো",
  "literacy.tutorial.step2Desc": "সাধাৰণ মোবাইলৰে ফটো তোলক। AI য়ে ব্যস্ত পটভূমি আঁতৰাই সুন্দৰ পোহৰ দিব।",
  "literacy.tutorial.step3Title": "৩. উচিত মূল্য নিৰ্ধাৰণ পৰামৰ্শ",
  "literacy.tutorial.step3Desc": "কেঁচামাল আৰু আপোনাৰ দৈনিক মজুৰি যোগ কৰি উপযুক্ত মূল্য স্থিৰ কৰা হয়।",
  "literacy.tutorial.step4Title": "৪. পোনপটীয়াকৈ বেংক একাউণ্টত ধন (DBT)",
  "literacy.tutorial.step4Desc": "গ্ৰাহকৰ ধন পোনে পোনে আপোনাৰ বেংক একাউণ্টত জমা হয়। কোনো মধ্যভোগী নাই।",
